    readMinutes: 8, heroImage: '/blog/reviewing-plan-inclusions.webp', heroAlt: 'Australian builder reviewing service-plan inclusions at a site office desk',
    secondaryImage: '/blog/tradierelay-call-rules.png', secondaryAlt: 'TradieRelay configuration showing the live call scope behind a plan', secondaryCaption: 'A plan name is not a scope. The proposal should name the actual answering rule, people, routes, limits and review rhythm.',
    keyPoints: ['Ask what is included before asking for a discount.', 'Get usage and overage rules in writing.', 'Require a line between live capability and future work.'],
