    slug: 'is-customer-call-data-safe-ai-receptionist', number: 55, category: 'Cost, privacy & trust',
    title: 'Is Customer Call Data Safe with an AI Receptionist?',
    description: 'The questions Australian tradies should ask about customer details, photos, transcripts, providers, access and deletion.',
    directAnswer: 'Customer call data can be handled safely only when the provider uses clear collection notices, limited data, account separation, access controls, secure links, vetted subprocessors, retention rules and incident procedures. No provider should promise zero risk. TradieRelay separates records by business account, uses scoped expiring links, validates provider webhooks and stores customer photos in tenant-specific private paths, while the operator remains responsible for ongoing controls and deletion decisions.',
    readMinutes: 9, heroImage: '/blog/customer-data-security-review.webp', heroAlt: 'Australian trade business owner reviewing customer-data access controls with a security specialist',
    secondaryImage: '/blog/tradierelay-dashboard.png', secondaryAlt: 'TradieRelay dashboard showing one business account with its calls and jobs', secondaryCaption: 'A tradie should see only the customers and jobs for their own business. Fake demo data is shown in public screens.',
    keyPoints: ['Ask where data flows and who can access it.', 'Collect only information needed for the job decision.', 'Security includes deletion and incident response—not just passwords.'],
    sections: [
      { heading: 'Know what the system holds', bullets: ['Caller name and phone number', 'Suburb, address and job description when provided', 'Transcript, summary and confidence information', 'Recording link only where recording is enabled', 'Customer-uploaded photos', 'Quote, message and activity history'] },
      { heading: 'Check account separation and access', paragraphs: ['TradieRelay queries business data by tenant identifier and stores uploaded photo paths under the same tenant and job. Customer and tradie links are hashed, scoped to a specific action and expire. Provider webhooks use signature checks. These controls reduce risk but still require configuration, monitoring and access review.'] },
      { heading: 'Understand the AI and provider data flow', paragraphs: ['The OAIC recommends due diligence on who can access personal information, whether provider terms allow data to be used for training, what settings can disable secondary use and how human oversight is embedded. Ask for the actual providers and regions, not a generic “secure AI” answer.'] },
      { heading: 'Minimise before protecting', paragraphs: ['Do not ask for identity documents, health details or unrelated personal information when a name, callback number, suburb and job description are enough. Less data reduces exposure and makes the caller experience shorter.'] },
      { heading: 'Plan deletion and incidents', paragraphs: ['APP 11 requires covered entities to take reasonable technical and organisational security steps and to destroy or de-identify personal information when it is no longer needed, subject to legal retention requirements. Every business should document retention, access removal and breach escalation.'], callout: { label: 'NO MAGIC WORD', text: '“Encrypted” is not a complete security answer. Ask about access, provider use, tenant separation, links, logs, retention, deletion and incidents.' } },
    ],
    example: { title: 'A customer uploads a leaking-pipe photo', text: 'The customer receives a time-limited upload link scoped to one job. The file is stored under that business and job, then displayed to the authorised tradie through the app route. The business decides how long it is needed and removes access when staff leave.' },
    productVisual: 'dashboard', productCaption: 'The working account view combines job details and evidence inside the correct tenant rather than sending loose customer photos between unrelated inboxes.',
    table: { headers: ['Question', 'Good evidence'], rows: [['Who can see it?', 'Role and tenant access controls'], ['How is a link protected?', 'Scoped, expiring, revocable token'], ['Can the AI provider reuse it?', 'Written terms and disabled training where required'], ['How long is it kept?', 'Documented retention schedule'], ['What happens after a breach?', 'Named response and notification process']] },
    checklist: ['Map collected fields.', 'List every provider.', 'Check data-use terms.', 'Verify tenant separation.', 'Use scoped expiring links.', 'Restrict operator access.', 'Set staff offboarding.', 'Choose retention periods.', 'Document deletion.', 'Test incident escalation.'],
    faqs: [{ question: 'Does the Privacy Act cover every small tradie?', answer: 'Most businesses with turnover of $3 million or less are not covered, but important exceptions apply. OAIC provides a small-business checklist. Good privacy practice remains valuable even where the Act does not apply.' }, { question: 'Does TradieRelay use public demo customer data?', answer: 'Public screens use fictional demo data. Live customer records belong in the authenticated business account.' }, { question: 'Can customer photos be sent by ordinary SMS?', answer: 'TradieRelay sends a secure upload link so photos attach to the job. The SMS contains the link, not the image itself.' }],
    sources: [{ label: 'OAIC: privacy and commercially available AI products', url: 'https://www.oaic.gov.au/privacy/privacy-guidance-for-organisations-and-government-agencies/guidance-on-privacy-and-the-use-of-commercially-available-ai-products' }, { label: 'OAIC: APP 11 security of personal information', url: 'https://www.oaic.gov.au/privacy/australian-privacy-principles/australian-privacy-principles-guidelines/chapter-11-app-11-security-of-personal-information' }, { label: 'OAIC: small business and the Privacy Act', url: 'https://www.oaic.gov.au/privacy/privacy-guidance-for-organisations-and-government-agencies/organisations/small-business' }],
